import React, { useState } from 'react';

// Create the EventHandlingDemo component here
const EventHandlingDemo = () => {
  // Initialize count state here
  const [count, setCount] = useState<number>(0);
  const [inputValue, setInputValue] = useState<string>('');

  // Define handleIncrement function here
  const handleIncrement = () => {
    setCount(count + 1);
  };

  // Define handleReset function here
  const handleReset = () => {
    setCount(0);
  };

  // Define handleChange function here
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
  };

  return (
    <div>
      {/* Add paragraph displaying count here */}
      <p>Count: {count}</p>
      <button onClick={handleIncrement}>Increment</button>
      {/* Add reset button here */}
      <button onClick={handleReset}>Reset</button>
      {/* Add input field here */}
      <input type="text" value={inputValue} onChange={handleChange} />
      {/* Add paragraph to display input value here */}
    </div>
  );
};
